  "supportive_card_ids": ["C246", "C264", "C253", "C259", "C267", "C237", "C87", "C89"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C246", "C264", "C253", "C259", "C87", "C89"],
  "claims": [
    {
      "claim": "L6 hepatic evidence shows fluoroquinolones have low to moderate hepatic extraction: moxifloxacin hepatic extraction is 26% in humans (C246) and human hepatocyte intrinsic clearance is only 1.56 µL/min/10^6 cells (C267), supporting high systemic availability after absorption.",
      "card_ids": ["C246", "C267"]
    },
    {
      "claim": "Levofloxacin has the lowest HLM intrinsic clearance among four fluoroquinolones (C264) and ofloxacin undergoes only minor CYP demethylation and N-oxidation (C259), indicating minimal hepatic first-pass loss for the class.",
      "card_ids": ["C264", "C259"]
    },
    {
      "claim": "Ciprofloxacin, the least bioavailable fluoroquinolone in the class, still has only 12-19% hepatic CYP metabolism (C253), so hepatic clearance does not drive F below 20% for this scaffold.",
      "card_ids": ["C253"]
    },
    {
      "claim": "Direct human oral/IV AUC ratios for moxifloxacin, the closest analog with the same cyclopropyl core and C8 methoxy, are 0.91-0.92 (C87, C89), and L6 shows its hepatic extraction is only 26% (C246), together supporting F >= 20% for the query.",
      "card_ids": ["C87", "C89", "C246"]
    },
    {
      "claim": "Antofloxacin, a C7 amino-piperidine fluoroquinolone with high human oral bioavailability, has a low rat model intrinsic clearance of 4.28 ml/min (C237), consistent with low hepatic first-pass loss for this structural family.",
      "card_ids": ["C237"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C246", "C264", "C253", "C259", "C267", "C237", "C252"]
    }
  ],
  "evidence_gaps": [
    "No direct hepatic clearance or metabolic stability measurement exists for the query molecule itself.",
    "The metabolic fate of the query-specific C7 fluoroalkene primary amine is unknown; it could undergo conjugation or oxidation not captured by analog records.",
    "Moxifloxacin hepatic extraction data come from 100 mg doses and population PK contexts; the query dose and formulation are unknown.",
    "No direct absolute oral bioavailability measurement exists for the query molecule."
  ],
  "decision_summary": "L6 hepatic clearance and metabolic stability records show the fluoroquinolone class has low to moderate hepatic extraction (moxifloxacin 26%, ciprofloxacin 12-19% hepatic metabolism, levofloxacin lowest CLint), which supports rather than undermines high oral bioavailability. No L6 record affirmatively shows high first-pass loss for the query or a close analog. Combined with direct human F and oral/IV AUC ratios for the class, the prediction remains high and is strengthened; confidence remains high."
}

